"""Starts a local testnet: 3 connected nodes + 1 miner (4 processes), with a genesis generated by `netgen`.

    PYTHONPATH=. python scripts/run_local_testnet.py --dir local-testnet [--block-time 4] [--base-p2p 18333]

Creates in --dir: genesis.json, miner.wallet.json (the miner's wallet; default devnet password or the variable
WINFLUX_DEVNET_PASSWORD), <node>/ (data) and logs/<node>.log. Ports: P2P base..base+3 and API base..base+3, on 127.0.0.1.
Ctrl+C stops everything. Use `--keep` to reuse the directory (resumes the chain).
LOCAL tests only: do not use the keys/password from here with real money.
"""
import argparse
import os
import signal
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from winflux.tools.localnet import DEFAULT_PASSWORD, LocalTestnet  # noqa: E402


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--dir", default="local-testnet")
    ap.add_argument("--nodes", type=int, default=3, help="non-mining nodes (default 3); the miner is one extra node")
    ap.add_argument("--block-time", type=int, default=4, help="desired seconds per block (calibrates the difficulty)")
    ap.add_argument("--base-p2p", type=int, default=18333)
    ap.add_argument("--base-api", type=int, default=18080)
    ap.add_argument("--keep", action="store_true", help="do not delete the directory: resumes the previous network")
    ap.add_argument("--log-level", default="info", choices=["debug", "info", "warning", "error"])
    ap.add_argument("--duration", type=int, default=0, help="stops by itself after N seconds (0 = until Ctrl+C)")
    a = ap.parse_args(argv)

    net = LocalTestnet(a.dir, nodes=a.nodes, base_p2p=a.base_p2p, base_api=a.base_api,
                       block_time=a.block_time, log_level=a.log_level)
    print("calibrating difficulty and generating the genesis...", flush=True)
    net.prepare(fresh=not a.keep)
    stop = []
    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, lambda *_: stop.append(1))
    try:
        net.start()
        print(f"\nLocal testnet is up (network {net.chain_id})")
        for n in net.nodes:
            print(f"  {n.name:<7} P2P 127.0.0.1:{n.p2p_port}  API {n.api}" + ("  [mining]" if n.mine else "")
                  + f"  log {os.path.relpath(n.log_path)}")
        print(f"\n  genesis: {os.path.relpath(net.genesis_path)}")
        print(f"  miner wallet: {os.path.relpath(net.wallet_path)}  (address {net.miner_address})")
        if net.password == DEFAULT_PASSWORD:
            print("  WARNING: default devnet password; use only for local tests.")
        print("\nExemplos:")
        print(f"  curl -s {net.nodes[0].api}/api/status")
        print(f"  WINFLUX_WALLET_PASSWORD='{DEFAULT_PASSWORD}' PYTHONPATH=. python -m winflux.cli "
              f"--node {net.nodes[1].api} --wallet {os.path.relpath(net.wallet_path)} balance")
        print("\nCtrl+C to stop.", flush=True)
        end = time.time() + a.duration if a.duration else None
        while not stop and (end is None or time.time() < end):
            dead = [n for n in net.nodes if not n.alive()]
            if dead:
                print(f"ERROR: {dead[0].name} stopped:\n{net.tail(dead[0])}", file=sys.stderr)
                return 1
            time.sleep(0.5)
    except RuntimeError as e:
        print(f"ERROR: {e}", file=sys.stderr)
        return 1
    finally:
        print("\nshutting down nodes...", flush=True)
        net.stop()
    return 0


if __name__ == "__main__":
    sys.exit(main())
